// Shape of Mush/derived/ship-layout.json, generated by `npm run ship-layout`
// from Motion Twin's ShipMap.png and tiles.xml. The data file is CC BY-NC-SA;
// these types are ours. Positions are isometric grid cells, not pixels.

export type TileKind =
  /** Walkable floor (base layer, slice flagged `_pathable`). */
  | "ground"
  /** Non-walkable base-layer tile. */
  | "wall"
  /** A wall tile that is a door; see `TilePlacement.door`. */
  | "door"
  /** Single-cell decoration from the props layer. */
  | "prop"
  /** Object with a footprint (furniture, consoles, chairs, cameras). */
  | "entity";

export interface TilePlacement {
  x: number;
  y: number;
  kind: TileKind;
  /** Which of the four source layers it came from (0 base, 1 props, 2 non-pathable, 3 extra). */
  layer: 0 | 1 | 2 | 3;
  slice: string;
  frame: number;
  /** Present when `kind` is "door". */
  door?: { target: string };
}

export interface RoomLayout {
  /** Original room id, e.g. "CORRIDOR_A". */
  id: string;
  /** English label, from the row labels drawn in ShipMap.png. */
  label: string;
  tiles: TilePlacement[];
  /** Equipment-to-sprite bindings from tiles.xml `<extras>`, in source order. */
  equipment: EquipmentBinding[];
}

export interface EquipmentBinding {
  /** Equipment (item) id, e.g. "KITCHEN". */
  id: string;
  /** Slice id of the sprite that represents it. */
  tile: string;
  mask?: string;
  dir?: string;
  module?: boolean;
  key?: string;
  /** Raw extra data, e.g. "flipped;ofsx_-18;ofsy_-2". */
  data?: string;
}

export interface SheetInfo {
  /** Path relative to the Mush/ folder. */
  image: string;
  width: number;
  height: number;
  /** Color the original client made transparent at load time, as "rrggbbaa". */
  transparentColor?: string;
}

export interface SliceFrame {
  /** Map color (rrggbb) that places this frame, if any. */
  color?: string;
  groundOffsetY?: number;
  dir?: string;
}

export interface SliceAnim {
  frames: number[];
  rhythm: number[];
  auto: boolean;
}

/** One sprite definition. Frame i is at x + (i % framesX) * width, y + floor(i / framesX) * height. */
export interface SliceInfo {
  sheet: string;
  x: number;
  y: number;
  width: number;
  height: number;
  framesX: number;
  framesY: number;
  flipX: boolean;
  flipY: boolean;
  rot: number;
  /** Draw offset in pixels. */
  offset: [number, number];
  /** Behavior flags from `data="..."`, lowercased without the underscore, e.g. "pathable", "door". */
  flags: string[];
  /** Cells covered, extending toward -x/-y from the anchor cell. */
  footprint?: [number, number];
  frames: SliceFrame[];
  anims: SliceAnim[];
  engine?: string;
  dir?: string;
  modulePad?: [number, number];
  /**
   * As written in the XML. The original client read a `prio` attribute that
   * the XML never uses, so this was effectively always 0 there.
   */
  prioOffset?: number;
  /** Alternate looks, state id -> slice id. */
  states?: Record<string, string>;
}

/** One entry of Mush/derived/ship-rooms.json: the room graph, without any art. */
export interface ShipRoom {
  id: string;
  label: string;
  /** Rooms reachable through this room's doors, sorted. */
  doors: string[];
  /** Equipment drawn in this room (see `placedEquipment`). */
  equipment: { id: string; type: string }[];
}

export interface ShipLayout {
  /** Rooms are roomSize x roomSize cells in ShipMap.png; the corridors we stretch (tools/src/shipLayout/stretch.ts) can be larger. */
  roomSize: number;
  sheets: Record<string, SheetInfo>;
  slices: Record<string, SliceInfo>;
  rooms: RoomLayout[];
  /** Equipment bound to a sprite wherever it appears (tiles.xml `<autoBind>`). */
  autoBind: { id: string; tile: string }[];
}

/** A piece of equipment that is drawn in a room, tied to the tile that draws it. */
export interface PlacedEquipment {
  /** Unique across the ship, e.g. "REFECTORY:KITCHEN" or "BEDROOM_A:bed_a_b". */
  id: string;
  /** Equipment type, e.g. "BED" (see equipment.ts). */
  type: string;
  /** Index into the room's `tiles`. */
  tile: number;
}

/**
 * Equipment that is actually drawn in a room. Each binding claims the next
 * unclaimed tile with its sprite, in source order (three beds share one
 * sprite). Bindings with no tile on the map (things built later in the
 * original, like the Mycoscan) are left out. Used by the build tool for the
 * rules and by the renderer for clicks, so both agree.
 */
export function placedEquipment(room: RoomLayout): PlacedEquipment[] {
  const claimed = new Set<number>();
  const result: PlacedEquipment[] = [];
  for (const b of room.equipment) {
    const tile = room.tiles.findIndex((t, i) => !claimed.has(i) && t.slice === b.tile);
    const id = `${room.id}:${b.key ?? b.id}`;
    if (tile < 0 || result.some((e) => e.id === id)) continue;
    claimed.add(tile);
    result.push({ id, type: b.id, tile });
  }
  return result;
}

/** A horizontal strip of cells: x, y, length. */
export type CellRun = [x: number, y: number, length: number];

/**
 * Shape of Mush/derived/ship-plan.json: the flat, top-down deck plan of the
 * ship the original game used for its minimap (Map.hx `GfxData`). One cell is
 * one pixel of the original plan; (0, 0) is the top-left wall.
 */
export interface ShipPlan {
  width: number;
  height: number;
  /** Every room with doors, as runs of floor cells. */
  rooms: { id: string; runs: CellRun[] }[];
  /** Each door joins exactly two rooms and sits in the wall between them. */
  doors: { rooms: [string, string]; cells: [x: number, y: number][] }[];
  walls: CellRun[];
}
